/**
 * Docusaurus: docs under F/docs (or the docs plugin's `path:`), sidebars.{js,ts,json,cjs,mjs} read
 * statically (lib/repo/jsliteral.mjs: never executed). The first sidebar is the nav, the others
 * become tabs. Items: "doc/id", {type: doc|ref, id, label}, {type: category, label, items, link},
 * {type: autogenerated, dirName}, {type: link} (external, not imported); shorthand categories
 * ({"Label": [...]}) too. An unreadable sidebars file, or none, → folders (_category_.json|yml
 * labels and positions, sidebar_position, number prefixes stripped like Docusaurus).
 * Brand from docusaurus.config by regex (title, tagline, favicon, navbar logo) and the colours in
 * src/css/custom.css; files from F/static.
 */
import { parse as parseYaml } from "yaml";
import { parseSidebarsFile } from "../jsliteral.mjs";
import { humanize, joinRepo, normRepoPath, pathSegment, relTo, stemOf, stripNumberPrefix } from "../paths.mjs";
import { folderNav, isIndexFile } from "./folders.mjs";

const SIDEBAR_FILES = ["sidebars.js", "sidebars.ts", "sidebars.json", "sidebars.cjs", "sidebars.mjs"];

/** A doc's Docusaurus id: its folder (number prefixes stripped) + its front matter id or file name. */
export function docId(rel, fm = {}) {
  const segs = rel.split("/");
  const name = segs.pop();
  const dir = segs.map(stripNumberPrefix);
  const id = typeof fm.id === "string" || typeof fm.id === "number" ? String(fm.id) : stripNumberPrefix(stemOf(name));
  return [...dir, id].join("/");
}

/** A doc's URL path under the docs route (without it), as segments: front matter slug, else the id path. */
export function docUrlSegments(rel, fm = {}) {
  const segs = rel.split("/");
  const name = segs.pop();
  const dir = segs.map(stripNumberPrefix);
  if (typeof fm.slug === "string" && fm.slug.trim()) {
    const s = fm.slug.trim();
    const parts = s.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
    return s.startsWith("/") ? parts : [...dir, ...parts];
  }
  if (isIndexFile(rel, { folderNamed: true }) && fm.id === undefined) return dir;
  const id = fm.id !== undefined ? String(fm.id) : stripNumberPrefix(stemOf(name));
  return [...dir, id];
}

function categoryOf(env, root) {
  return (dir) => {
    for (const n of ["_category_.json", "_category_.yml", "_category_.yaml"]) {
      const f = joinRepo(root, dir, n);
      const t = env.files.has(f) ? env.readText(f) : null;
      if (t == null) continue;
      try {
        const v = n.endsWith(".json") ? JSON.parse(t) : parseYaml(t, { logLevel: "silent" });
        if (v && typeof v === "object") return { label: typeof v.label === "string" ? v.label : undefined, position: Number.isFinite(Number(v.position)) ? Number(v.position) : undefined };
      } catch {
        env.note(`${f} couldn't be read`);
      }
    }
    return null;
  };
}

/** The sidebars file named in the config (sidebarPath), or the usual names. */
function sidebarsFile(env) {
  const F = env.det.folder;
  const cfg = env.det.config ? env.readText(env.det.config) ?? "" : "";
  const m = /sidebarPath\s*:\s*(?:require\.resolve\(\s*)?['"`]([^'"`]+)['"`]/.exec(cfg);
  if (m) {
    const p = joinRepo(F, normRepoPath(m[1].replace(/^\.\//, "")) ?? "");
    if (env.files.has(p)) return p;
  }
  return SIDEBAR_FILES.map((n) => joinRepo(F, n)).find((p) => env.files.has(p)) ?? null;
}

export default {
  name: "docusaurus",
  flavor: "docusaurus",
  natural(page) {
    return docUrlSegments(page.rel, page.fm);
  },
  nav(env) {
    const root = env.det.contentRoot;
    const category = categoryOf(env, root);
    const byId = new Map();
    for (const p of env.pages) byId.set(docId(p.rel, p.fm), p);
    const autogen = (dirName) => {
      const dir = joinRepo(root, normRepoPath(String(dirName ?? ".").replace(/^\.\/?/, "")) ?? "");
      return folderNav(env.pages, { root: dir, category: (d) => category(relTo(joinRepo(dir, d), root)), folderNamed: true });
    };
    const folders = () => {
      const f = autogen(".");
      return { groups: f.groups, tabs: [], navTitles: new Map(), home: null, redirects: [] };
    };
    const file = sidebarsFile(env);
    if (!file) return folders();
    let sidebars;
    try {
      sidebars = parseSidebarsFile(env.readText(file) ?? "", file);
    } catch (e) {
      env.note(`${file} isn't a plain object (${e.message}): the sidebar follows the folders`);
      return folders();
    }
    if (!sidebars || typeof sidebars !== "object" || Array.isArray(sidebars) || !Object.keys(sidebars).length) {
      env.note(`${file} has no sidebars: the sidebar follows the folders`);
      return folders();
    }
    const navTitles = new Map();
    const missing = new Set();
    const items = (v) => (Array.isArray(v) ? v : v && typeof v === "object" ? Object.entries(v).map(([label, its]) => ({ type: "category", label, items: its })) : []);
    const docFile = (id, label) => {
      const p = byId.get(String(id ?? "").replace(/^\/+/, ""));
      if (!p) {
        missing.add(String(id));
        return null;
      }
      if (label) navTitles.set(p.file, String(label));
      return p.file;
    };
    // Every doc of an item, in order (categories flattened, their link doc first).
    const flat = (it, out) => {
      if (typeof it === "string") {
        const f = docFile(it);
        if (f) out.push(f);
        return out;
      }
      if (!it || typeof it !== "object") return out;
      const type = it.type ?? (it.items ? "category" : it.id ? "doc" : it.href ? "link" : null);
      if (type === "doc" || type === "ref") {
        const f = docFile(it.id, it.label);
        if (f) out.push(f);
      } else if (type === "category") {
        if (it.link?.type === "doc") {
          const f = docFile(it.link.id);
          if (f) out.push(f);
        }
        for (const x of items(it.items)) flat(x, out);
      } else if (type === "autogenerated") out.push(...autogen(it.dirName).groups.flatMap((g) => g.files));
      else if (type === "link") env.external.push({ title: it.label ?? it.href, href: it.href });
      else if (!it.type && typeof it === "object") for (const x of items(it)) flat(x, out);
      return out;
    };
    const names = Object.keys(sidebars);
    const tabs = names.length > 1 ? names.map((n) => ({ id: pathSegment(n), label: humanize(n.replace(/Sidebar$/i, "") || n) })) : [];
    const groups = [];
    names.forEach((name, si) => {
      const tab = tabs[si]?.id;
      let run = [];
      let runs = 0;
      const flush = () => {
        if (run.length) groups.push({ group: runs++ === 0 && !groups.some((g) => g.tab === tab) ? (tabs.length ? tabs[si].label : "Getting started") : "More", files: run, ...(tab ? { tab } : {}) });
        run = [];
      };
      for (const it of items(sidebars[name])) {
        const type = typeof it === "string" ? "doc" : it?.type ?? (it?.items ? "category" : it?.id ? "doc" : it?.href ? "link" : null);
        if (type === "category") {
          flush();
          const files = flat(it, []);
          if (files.length) groups.push({ group: String(it.label ?? "Docs"), files, ...(tab ? { tab } : {}) });
        } else if (type === "autogenerated") {
          flush();
          for (const g of autogen(it.dirName).groups) groups.push({ ...g, ...(tab ? { tab } : {}) });
        } else flat(it, run);
      }
      flush();
    });
    for (const id of missing) env.note(`The sidebar lists the doc “${id}”, which isn't in ${root || "the folder"}: left out`);
    return { groups, tabs, navTitles, home: null, redirects: [] };
  },
  brand(env) {
    const cfg = env.det.config ? env.readText(env.det.config) ?? "" : "";
    const str = (re) => re.exec(cfg)?.[1];
    const stat = (v) => (v && !/^[a-z]+:/i.test(v) ? joinRepo(env.det.staticDir, normRepoPath(v.replace(/^\.?\/+/, "")) ?? "") || null : null);
    const logoBlock = /navbar\s*:\s*\{[\s\S]*?logo\s*:\s*\{([\s\S]*?)\}/.exec(cfg)?.[1] ?? "";
    const logoSrc = /\bsrc\s*:\s*['"`]([^'"`]+)['"`]/.exec(logoBlock)?.[1];
    const logoDark = /\bsrcDark\s*:\s*['"`]([^'"`]+)['"`]/.exec(logoBlock)?.[1];
    const logoAlt = /\balt\s*:\s*['"`]([^'"`]+)['"`]/.exec(logoBlock)?.[1];
    const css = env.readText(joinRepo(env.det.folder, "src/css/custom.css")) ?? "";
    const light = /:root\s*\{[^}]*--ifm-color-primary\s*:\s*(#[0-9a-fA-F]{3,8})\b/.exec(css)?.[1];
    const dark = /\[data-theme=['"]?dark['"]?\]\s*\{[^}]*--ifm-color-primary\s*:\s*(#[0-9a-fA-F]{3,8})\b/.exec(css)?.[1];
    return {
      name: str(/^\s*title\s*:\s*['"`]([^'"`]+)['"`]/m),
      description: str(/^\s*tagline\s*:\s*['"`]([^'"`]+)['"`]/m),
      logo: logoSrc && stat(logoSrc) ? { light: stat(logoSrc), ...(logoDark && stat(logoDark) ? { dark: stat(logoDark) } : {}), ...(logoAlt ? { alt: logoAlt } : {}) } : undefined,
      favicon: stat(str(/^\s*favicon\s*:\s*['"`]([^'"`]+)['"`]/m)) ?? undefined,
      accent: light,
      accentDark: dark,
    };
  },
};
